import{z as s,x as A,o as e,c as p,q as t,j as r,D as a,d as i,s as o,S as l,b as B}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"英式与荷式拍卖","description":"","frontmatter":{"title":"英式与荷式拍卖","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/english-dutch-auction.md","filePath":"econ/english-dutch-auction.md","lastUpdated":1791063341000}'),d={name:"econ/english-dutch-auction.md"};function C(h,E,c,D,u,m){const n=A("Mermaid");return e(),p("div",null,[E[2]||(E[2]=t('<h1 id="英式与荷式拍卖" tabindex="-1">英式与荷式拍卖 <a class="header-anchor" href="#英式与荷式拍卖" aria-label="Permalink to &quot;英式与荷式拍卖&quot;">​</a></h1><div class="epigraph"><p>荷式降价与第一价格密封是同一场博弈；独立私值下，英式加价与第二价格密封策略等价——规则换皮，均衡策略可以原样搬。</p><footer>—— Vickrey, Journal of Finance, 1961；Krishna, Auction Theory</footer></div><p><a href="/econ/ipv-first-price">上一课</a>给出密封一价的对称 BNE：遮挡函数依赖 \\(F\\) 与 \\(n\\)。缺口是现场常见的是公开时钟，不是信封。降价拍卖（荷式）与加价拍卖（英式）看起来完全不像密封，是否要另解一套微分方程？策略等价说：不必。本课钉「同一策略式」与「IPV 下英式对二价」，不把占优真话写成定理——那是下一课维克里。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>荷式：价格从高往下走，第一位喊「停」的人按当前价得物。每人的策略是一个停止价 \\(b_i\\)。支付：停的人付 \\(b_i\\)，其余付零。这与密封一价的策略集、支付函数相同——只是物理上别人看得见时钟，却看不到别人的信封；在同时「选一个数」的意义上，信息集并不比密封多。故荷式的 BNE 就是上一课的 \\(b(v)\\)，不是新均衡。</p><p>英式（按钮 / 时钟）：价格往上走，未退出者都还在；最后留下的人按别人退出的价（第二高退出价）付款。IPV 下，别人的退出只告诉你他们的估值下限，不改变你对自己 \\(v\\) 的评价。占优策略是「价格碰到 \\(v\\) 再退」。配置与付款等于：最高估值者得物，付第二高估值——与二价密封同一结果。</p><p><span class="marginnote">数字实例：五人竞拍，估值 100、80、70、60、50。英式与密封二价：估值 100 者得物、付 80。一价与荷式：同一人得物，但按遮挡公式只报一个略低于 80 的数并照付。四种规则配置相同，分寸差在「付多少、怎么定」。</span></p><h3 id="策略等价强于收入相当" tabindex="-1">策略等价强于收入相当 <a class="header-anchor" href="#策略等价强于收入相当" aria-label="Permalink to &quot;策略等价强于收入相当&quot;">​</a></h3><p>策略等价：两个博弈的策略空间与支付函数一致（或差一个一一对应），均衡集相同。荷式 \\(=\\) 一价是这种。收入等价只说期望付款相同，策略可以完全不同——那是后课后一课的包络，本课不预支。英式与二价在 IPV 下策略等价（按钮模型）；口头英式若能看见是谁退出，共同价值里就不再等价，本课先锁 IPV。</p><p><span class="marginnote">Vickrey 1961 已经把四种经典拍卖放在同一张桌子上。Krishna 的教具把「按钮英式」写成退出价向量，便于和密封二价逐点对上。口头加价若允许跳价、合谋信号，策略空间更大，等价要加限制。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：对称 IPV、风险中性、单物品、无保留价。先把荷式写成同时选 \\(b_i\\) 的策略式，引用上一课的遮挡公式。再把英式写成「退出点 \\(=v_i\\)」，只陈述结果与二价相同；占优论证留给下一课。比较：公开与否在 IPV 一价 / 荷式里不提供新信息，因为赢不更新自己的 \\(v\\)。</p>',12)),(e(),r(l,null,{default:a(()=>[o(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FP%5B%22%E5%AF%86%E5%B0%81%E4%B8%80%E4%BB%B7%22%5D%20--%3E%20DUT%5B%22%E8%8D%B7%E5%BC%8F%E9%99%8D%E4%BB%B7%EF%BC%9A%E5%90%8C%E4%B8%80%E7%AD%96%E7%95%A5%E5%BC%8F%22%5D%0A%20%20DUT%20--%3E%20SHADE%5B%22%E5%90%8C%E4%B8%80%E9%81%AE%E6%8C%A1%20BNE%22%5D%0A%20%20ENG%5B%22%E8%8B%B1%E5%BC%8F%E5%8A%A0%E4%BB%B7%20IPV%22%5D%20--%3E%20SP%5B%22%E4%B8%8E%E4%BA%8C%E4%BB%B7%E5%90%8C%E4%B8%80%E9%85%8D%E7%BD%AE%E4%B8%8E%E4%BB%98%E6%AC%BE%22%5D%0A%20%20SP%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%8D%A0%E4%BC%98%E7%9C%9F%E8%AF%9D%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[i(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("p",null,"四种名称对应两场博弈。先问策略式是否相同（本课），再问期望收入是否相同（后课包络）。人数一变只改一价 / 荷式的 \\(b(\\cdot)\\)，英式的「退到 \\(v\\)」不动。",-1)),E[4]||(E[4]=B("h2",{id:"机制",tabindex:"-1"},[i("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=B("p",null,"荷式时钟不泄露对手的停止点——第一个停就结束，其余人的数从未显示。故「公开」没有信息含量，博弈缩回密封一价。英式相反：价格路径公开显示谁已退出。IPV 下这条路径只筛选「谁还在」，不改变你的价值数字，所以最优仍是按自己的 \\(v\\) 停；付款由对手的 \\(v\\) 钉住，自己的嘴只当门槛。",-1)),(e(),r(l,null,{default:a(()=>[o(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLK%5B%22%E5%85%AC%E5%BC%80%E6%97%B6%E9%92%9F%E5%88%B0%E5%BA%95%E6%B3%84%E9%9C%B2%E4%BA%86%E4%BB%80%E4%B9%88%EF%BC%9F%22%5D%20--%3E%20DUT%5B%22%E8%8D%B7%E5%BC%8F%EF%BC%9A%E4%BB%B7%E6%A0%BC%E4%B8%8B%E8%A1%8C%22%5D%0A%20%20CLK%20--%3E%20ENG%5B%22%E8%8B%B1%E5%BC%8F%EF%BC%9A%E4%BB%B7%E6%A0%BC%E4%B8%8A%E8%A1%8C%20%2B%20%E8%B0%81%E9%80%80%E5%87%BA%E4%BA%86%22%5D%0A%20%20DUT%20--%3E%20D1%5B%22%E7%AC%AC%E4%B8%80%E5%A3%B0%E3%80%8C%E5%81%9C%E3%80%8D%E5%8D%B3%E7%BB%93%E6%9D%9F%EF%BC%8C%E5%AF%B9%E6%89%8B%E7%9A%84%E5%81%9C%E6%AD%A2%E7%82%B9%E4%BB%8E%E6%9C%AA%E5%85%AC%E5%BC%80%22%5D%0A%20%20D1%20--%3E%20D2%5B%22%E9%9B%B6%E6%96%B0%E4%BF%A1%E6%81%AF%20%E2%86%92%20%E7%BC%A9%E5%9B%9E%E5%AF%86%E5%B0%81%E4%B8%80%E4%BB%B7%E7%9A%84%20BNE%22%5D%0A%20%20ENG%20--%3E%20E1%5B%22%E9%80%80%E5%87%BA%E4%BB%B7%E9%80%90%E4%B8%80%E5%85%AC%E5%BC%80%EF%BC%9A%E5%8F%AA%E9%80%8F%E9%9C%B2%E5%AF%B9%E6%89%8B%E4%BC%B0%E5%80%BC%E7%9A%84%E4%B8%8B%E9%99%90%22%5D%0A%20%20E1%20--%3E%20E2%5B%22IPV%20%E4%B8%8B%E4%B8%8D%E6%94%B9%E5%8F%98%E8%87%AA%E5%B7%B1%E7%9A%84%20v%20%E2%86%92%20%E4%BB%8D%E6%8C%89%20v%20%E9%80%80%E5%87%BA%EF%BC%8C%E4%BB%98%E7%AC%AC%E4%BA%8C%E9%AB%98%20v%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[i(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p>一价 / 荷式里，同一个数字既当门槛又当付款，必须遮挡。英式把付款钉在别人退出价上——会计已经接近二价。本课只要读者承认：换场地不等于换博弈；先核对策略式，再决定要不要重算 \\(b(v)\\)。</p><p><span class="marginnote">术语翻译：策略等价就是「换张皮，同一盘棋」——两个博弈的策略空间与支付函数一一对应，均衡可以原样照搬。它不同于收入等价：后者只说期望掏的钱一样，玩法可以完全不同。读到「等价」先问是哪一种。</span></p><p>按钮英式（价格连续上升，未按退出者仍在）与口头英式不同：后者允许跳价、从场外进场、用举手节奏发信号。IPV 教具用按钮，才能与密封二价一一对上。荷式若允许「看到别人犹豫再决定」，策略空间也会膨胀，不再等于密封一价。等价定理的前提是策略式真的相同，不是拍卖行的名字相同。</p><h3 id="四种经典拍卖的位置" tabindex="-1">四种经典拍卖的位置 <a class="header-anchor" href="#四种经典拍卖的位置" aria-label="Permalink to &quot;四种经典拍卖的位置&quot;">​</a></h3><p>对称 IPV、风险中性：荷式与一价同一均衡；英式与二价同一均衡。两组之间期望收入是否相同，是收入等价的句子，本课不证。人数、分布一变，遮挡函数变，但荷式仍跟着一价变，不必对时钟另建模型。</p><p><span class="marginnote">风险厌恶会改变一价 / 荷式的遮挡，不改变英式「退到 \\(v\\)」的占优（论证不对期望积分）。关联价值下英式的公开退出有联动价值，荷式没有——赢家诅咒课再写，本课 IPV 最瘦。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>保留价、进入费改边界，不改「荷式 \\(=\\) 一价」的策略式。多物品、组合、软收盘网上英式超出本课。也不要把时钟写成连续簿的价格优先；这里没有队列，只有一次拍卖。</p><p>软收盘、最低加价、卖方保留价隐藏，都会让「英式 \\(=\\) 二价」出现缝：跳价与信号重新进入策略空间。本课按钮模型是为了把等价钉死；现场规则一松，就要回到策略式核对，不能凭拍卖名称套公式。</p><p><span class="marginnote">常见误区：以为「公开拍卖人人看得见」就一定信息更多。荷式的时钟在 IPV 下没泄露任何对手的数字——第一个喊停就散场；英式才逐个披露退出。信息量取决于规则让什么可见，不取决于现场热不热闹。</span></p><p>后课默认：IPV 下荷式沿用一价遮挡；英式沿用「按 \\(v\\) 退出」。下一课把二价密封的占优真话补成证明。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>荷式与密封一价是同一策略式，遮挡公式原样用。</li><li>IPV 英式与二价策略等价：最高估值者得物，付第二高。</li><li>策略等价是博弈相同；收入等价是后课的期望。</li><li>公开时钟在 IPV 荷式里不提供额外信息。</li><li>出处：Vickrey, <em>Journal of Finance</em>, 1961；Krishna, <em>Auction Theory</em>。</li></ul>',13))])}const f=s(d,[["render",C]]);export{F as __pageData,f as default};
